        x="1670.36976"
        stroke-linecap="null"
        stroke-linejoin="null"
        stroke-dasharray="null"
        stroke-width="0"
        fill="#000000"
      >
        {{ svgData.hr8AiStmP }} MPa
      </text>
    </g>
  </svg>
</template>
<script>
export default {
  props: {
    svgData: { type: Object, default: () => {} },
  },
  data() {
    return {
      svgRootDom: null,
    };
  },
  created() {},
  mounted() {
    let _this = this;
    this.svgRootDom = this.$refs.overview;
    if (_this.svgRootDom) {
      _this.adjustToFreezeWidth(_this.svgRootDom);
    }
    window.addEventListener("resize", () => {
      if (_this.svgRootDom) {
        _this.adjustToFreezeWidth(_this.svgRootDom);
      }
    });
  },
  methods: {
    adjustToFreezeWidth(rootSvg) {
      // var g = document.getElementById("g1").getBBox(); //元素g
      var g = this.$refs.overview_g.getBBox();
      var parentWidth = rootSvg.parentNode.offsetWidth; //svg父级的宽度
      var parentHeight = rootSvg.parentNode.offsetHeight; //svg父级的高度

      rootSvg.setAttribute("width", parentWidth);
      rootSvg.setAttribute("height", parentHeight);
      // viewBox="0 0 150 360
      // rootSvg.setAttribute("viewBox",`${g.x} ${g.y} ${g.width} ${g.height}`)
      rootSvg.setAttribute(
        "viewBox",
        "" +
          g.x +
          " " +
          (g.y - 30) +
          " " +
          (g.width + 30) +
          " " +
          (g.height + 40) +
          ""
      );
    },
  },
};
</script>

